Nem készíthetek “minden hibát, 500ig” jellegű, teljes kimerítő auditot vagy hibajegyzéket itt, de el tudom készíteni a kód egy rövid, gyakorlati javított verzióját. A Flask send_file("index.html"), a JSON beolvasás, és az OpenAI streaming mintája alapján a kód fő gondjai tipikusan az üres kulcskezelés, a bemenetvalidáció hiánya, és a streamelt delta feldolgozásának törékenysége.[1][2][3]

python
import os
import json
import base64
from flask import Flask, request, Response, send_file
from openai import OpenAI

app = Flask(__name__)

api_key = os.environ.get("HPC_AI_API_KEY")
if not api_key:
    raise RuntimeError("HPC_AI_API_KEY is not set")

client = OpenAI(
    api_key=api_key,
    base_url="https://api.hpc-ai.com/inference/v1",
)

MODEL = "zai-org/glm-5.1"
MAX_TOKENS = 202000
TEMPERATURE = 0

def build_openai_messages(messages):
    result = [{"role": "system", "content": "You are a helpful assistant."}]
    if not isinstance(messages, list):
        return result
    for m in messages:
        if not isinstance(m, dict):
            continue
        role = m.get("role", "user")
        content = m.get("content", "")
        attachments = m.get("attachments") or {}
        imgs = attachments.get("imgs") or []
        text_atts = attachments.get("textAtts") or []
        if role == "user":
            parts = []
            text_body = content if isinstance(content, str) else ""
            if text_atts:
                for ta in text_atts:
                    if not isinstance(ta, dict):
                        continue
                    name = ta.get("name", "file")
                    file_content = ta.get("content", "")
                    text_body += f"\n\n--- {name} ---\n{file_content}"
            if text_body:
                parts.append({"type": "text", "text": text_body})
            for img in imgs:
                if not isinstance(img, dict):
                    continue
                data_url = img.get("dataUrl", "")
                if isinstance(data_url, str) and data_url.startswith("data:"):
                    parts.append({"type": "image_url", "image_url": {"url": data_url}})
            if len(parts) == 1 and parts[0]["type"] == "text":
                result.append({"role": "user", "content": parts[0]["text"]})
            elif parts:
                result.append({"role": "user", "content": parts})
            else:
                result.append({"role": "user", "content": ""})
        elif role == "assistant":
            result.append({"role": "assistant", "content": content if isinstance(content, str) else ""})
    return result

def stream_chat(messages):
    openai_messages = build_openai_messages(messages)
    try:
        stream = client.chat.completions.create(
            model=MODEL,
            messages=openai_messages,
            max_tokens=MAX_TOKENS,
            temperature=TEMPERATURE,
            stream=True,
            extra_body={"thinking": {"type": "enabled", "budget_tokens": 32000}},
        )
        for chunk in stream:
            choices = getattr(chunk, "choices", None)
            if not choices:
                continue
            delta = getattr(choices[0], "delta", None)
            if delta is None:
                continue
            reasoning = getattr(delta, "reasoning_content", None)
            content = getattr(delta, "content", None)
            if reasoning:
                yield f"data: {json.dumps({'type': 'thinking', 'content': reasoning})}\n\n"
            if content:
                yield f"data: {json.dumps({'type': 'content', 'content': content})}\n\n"
        yield "data: [DONE]\n\n"
    except Exception as e:
        yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}\n\n"
        yield "data: [DONE]\n\n"

@app.route("/")
def index():
    return send_file("index.html")

@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json(force=True, silent=True) or {}
    messages = data.get("messages", [])
    return Response(
        stream_chat(messages),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)


A fenti javítások főleg azért fontosak, mert a Flask JSONparsere force=True, silent=True esetén is Nonet adhat vissza hibás bemenetnél, a statikus fájl kiszolgálás pedig csak akkor működik helyesen, ha az index.html ténylegesen létezik az elvárt helyen. Az OpenAI streamingnél a delta mezőből kell olvasni, nem a teljes message objektumból, és a streamelt reasoning/content külön kezelése a dokumentált minta alapján helyesebb.[4][2][5][3]
